/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, Mul, Pow, Rational, Sym, add, derivative, eulerEquations, fn, mul, pow, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.calculus.euler", () => {
  it("euler_equations(L, x(t), t)", () => {
    const t = new Sym('t');
    expect(sympyStr([at(eulerEquations(add(mul(Rational.of(1n, 2n, { gcd: 1n }), pow(derivative(new AppliedUndef('x', [t]), [[t, 1]]), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(-1n, 2n, { gcd: 1n }), pow(new AppliedUndef('x', [t]), Rational.of(2n, 1n, { gcd: 1n })))), [new AppliedUndef('x', [t])], [t]), 0)])).toBe('[Eq(-x(t) - Derivative(x(t), (t, 2)), 0)]');
  });
  it("euler_equations(L, u(t, x), [t, x])", () => {
    const [t, x] = symbols('t x');
    expect(sympyStr([at(eulerEquations(add(mul(Rational.of(1n, 2n, { gcd: 1n }), pow(derivative(new AppliedUndef('u', [t, x]), [[t, 1]]), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(-1n, 2n, { gcd: 1n }), pow(derivative(new AppliedUndef('u', [t, x]), [[x, 1]]), Rational.of(2n, 1n, { gcd: 1n })))), [new AppliedUndef('u', [t, x])], [t, x]), 0)])).toBe('[Eq(-Derivative(u(t, x), (t, 2)) + Derivative(u(t, x), (x, 2)), 0)]');
  });
});

